let rows = [];

for (const item of $input.all()) {
  if (Array.isArray(item.json)) rows.push(...item.json);
  else if (Array.isArray(item.json?.data)) rows.push(...item.json.data);
  else rows.push(item.json);
}

rows = rows
  .filter(r => r && r.ticker)
  .map(r => ({
    json: {
      ticker: String(r.ticker).trim().toUpperCase(),
      company_name: r.company_name || null,
      ai_subsector: r.ai_subsector || null
    }
  }));

if (!rows.length) {
  throw new Error('No active tickers found in ai_stock_universe.');
}

return rows;

function firstNode(name) {
  try {
    const arr = $(name).all();
    if (!arr || !arr.length) return {};
    return arr[0].json;
  } catch (e) {
    return {};
  }
}

const base = firstNode('Loop Over AI Stocks');
const ratiosRaw = firstNode('Fetch FMP Ratios TTM');
const keyRaw = firstNode('Fetch FMP Key Metrics TTM');
const growthRaw = firstNode('Fetch FMP Financial Growth');

const ratios = Array.isArray(ratiosRaw) ? (ratiosRaw[0] || {}) : ratiosRaw;
const key = Array.isArray(keyRaw) ? (keyRaw[0] || {}) : keyRaw;
const growth = Array.isArray(growthRaw) ? (growthRaw[0] || {}) : growthRaw;

const toNum = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
};

const round2 = v =>
  v === null || v === undefined || !Number.isFinite(v)
    ? null
    : Math.round(v * 100) / 100;

const round4 = v =>
  v === null || v === undefined || !Number.isFinite(v)
    ? null
    : Math.round(v * 10000) / 10000;

const clamp = v => Math.max(0, Math.min(100, v));

const scoreInverse = (value, cheap, expensive) => {
  const v = toNum(value);
  if (v === null || v <= 0) return null;
  return clamp(100 - ((v - cheap) / (expensive - cheap)) * 100);
};

const scoreDirect = (value, weak, strong) => {
  const v = toNum(value);
  if (v === null) return null;
  return clamp(((v - weak) / (strong - weak)) * 100);
};

const weightedAverage = pairs => {
  const valid = pairs.filter(
    p => p.score !== null && p.score !== undefined && Number.isFinite(p.score)
  );

  if (!valid.length) return null;

  const totalW = valid.reduce((s, p) => s + p.weight, 0);
  return valid.reduce((s, p) => s + p.score * p.weight, 0) / totalW;
};

const safeDiv = (a, b) => {
  if (
    a === null ||
    a === undefined ||
    b === null ||
    b === undefined ||
    !Number.isFinite(a) ||
    !Number.isFinite(b) ||
    b === 0
  ) {
    return null;
  }

  return a / b;
};

const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Singapore',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(new Date());

const runDate = `${parts.find(p => p.type === 'year').value}-${parts.find(p => p.type === 'month').value}-${parts.find(p => p.type === 'day').value}`;

const ticker = String(
  base.ticker || key.symbol || ratios.symbol || growth.symbol || ''
).toUpperCase();

if (!ticker) {
  return [
    {
      json: {
        run_date_sgt: runDate,
        ticker: null,
        error: 'Ticker could not be resolved.',
        source: 'financial_modeling_prep',
      },
    },
  ];
}

// ============================================================
// Valuation Inputs
// ============================================================

const pe = toNum(
  key.peRatioTTM ??
  ratios.peRatioTTM ??
  ratios.priceEarningsRatioTTM
);

const evEbitda = toNum(
  key.enterpriseValueOverEBITDATTM ??
  key.evToEbitdaTTM ??
  ratios.enterpriseValueMultipleTTM
);

const evSales = toNum(
  key.evToSalesTTM ??
  key.enterpriseValueOverRevenueTTM
);

const ps = toNum(
  ratios.priceToSalesRatioTTM ??
  key.priceToSalesRatioTTM
);

const pb = toNum(
  ratios.priceToBookRatioTTM ??
  key.pbRatioTTM
);

const fcfYield = toNum(
  key.freeCashFlowYieldTTM ??
  key.fcfYieldTTM
);

const earningsYield = pe && pe > 0 ? 1 / pe : null;

const price = toNum(
  key.stockPrice ??
  key.price
);

const marketCap = toNum(
  key.marketCapTTM ??
  key.marketCap
);

// ============================================================
// FMP Field Mapping + Derived Efficiency Inputs
// ============================================================

const enterpriseValue = toNum(
  key.enterpriseValueTTM ??
  key.enterpriseValue ??
  key.evTTM ??
  key.ev
);

let revenue = toNum(
  key.revenueTTM ??
  key.revenue ??
  key.totalRevenueTTM ??
  key.totalRevenue
);

let ebitda = toNum(
  key.ebitdaTTM ??
  key.ebitda
);

let freeCashFlow = toNum(
  key.freeCashFlowTTM ??
  key.freeCashFlow ??
  key.fcfTTM ??
  key.fcf
);

// Fallback derivations.
// These are mathematically consistent with the ratio fields:
// revenue / EV = 1 / EV/Sales
// EBITDA / EV = 1 / EV/EBITDA
// FCF = FCF yield * market cap
if (revenue === null && enterpriseValue !== null && evSales !== null && evSales !== 0) {
  revenue = enterpriseValue / evSales;
}

if (ebitda === null && enterpriseValue !== null && evEbitda !== null && evEbitda !== 0) {
  ebitda = enterpriseValue / evEbitda;
}

if (freeCashFlow === null && fcfYield !== null && marketCap !== null) {
  freeCashFlow = fcfYield * marketCap;
}

const revenuePerEV = safeDiv(revenue, enterpriseValue);
const ebitdaPerEV = safeDiv(ebitda, enterpriseValue);
const fcfPerEV = safeDiv(freeCashFlow, enterpriseValue);

// ============================================================
// Growth / Quality Inputs
// ============================================================

const revenueGrowth = toNum(
  growth.revenueGrowth ??
  growth.growthRevenue
);

const netIncomeGrowth = toNum(
  growth.netIncomeGrowth ??
  growth.growthNetIncome
);

const grossMargin = toNum(
  ratios.grossProfitMarginTTM ??
  ratios.grossProfitMargin
);

const operatingMargin = toNum(
  ratios.operatingProfitMarginTTM ??
  ratios.operatingProfitMargin
);

const netMargin = toNum(
  ratios.netProfitMarginTTM ??
  ratios.netProfitMargin
);

const roe = toNum(
  ratios.returnOnEquityTTM ??
  ratios.roeTTM
);

const roic = toNum(
  ratios.returnOnInvestedCapitalTTM ??
  ratios.roicTTM
);

const debtToEquity = toNum(
  ratios.debtEquityRatioTTM ??
  ratios.debtToEquityTTM
);

const netDebtToEbitda = toNum(
  key.netDebtToEBITDATTM ??
  key.netDebtToEbitdaTTM
);

// ============================================================
// Component Scores
// ============================================================

const peScore = scoreInverse(pe, 15, 80);
const evEbitdaScore = scoreInverse(evEbitda, 8, 45);
const fcfYieldScore = scoreDirect(fcfYield, -0.02, 0.08);
const evSalesScore = scoreInverse(evSales, 3, 25);

const growthScore = weightedAverage([
  { score: scoreDirect(revenueGrowth, -0.10, 0.30), weight: 0.65 },
  { score: scoreDirect(netIncomeGrowth, -0.20, 0.40), weight: 0.35 },
]);

const qualityScore = weightedAverage([
  { score: scoreDirect(grossMargin, 0.25, 0.80), weight: 0.20 },
  { score: scoreDirect(operatingMargin, 0.05, 0.40), weight: 0.25 },
  { score: scoreDirect(netMargin, 0.00, 0.35), weight: 0.20 },
  { score: scoreDirect(roe, 0.05, 0.40), weight: 0.20 },
  { score: scoreDirect(roic, 0.04, 0.25), weight: 0.15 },
]);

const balanceSheetScore = weightedAverage([
  { score: scoreInverse(debtToEquity, 0.2, 3.0), weight: 0.55 },
  { score: scoreInverse(netDebtToEbitda, 0.0, 5.0), weight: 0.45 },
]);

const valuationScore = weightedAverage([
  { score: peScore, weight: 0.35 },
  { score: evEbitdaScore, weight: 0.30 },
  { score: fcfYieldScore, weight: 0.25 },
  { score: evSalesScore, weight: 0.10 },
]);

const growthQualityScore = weightedAverage([
  { score: growthScore, weight: 0.45 },
  { score: qualityScore, weight: 0.40 },
  { score: balanceSheetScore, weight: 0.15 },
]);

const fundamentalScore = weightedAverage([
  { score: valuationScore, weight: 0.55 },
  { score: growthQualityScore, weight: 0.45 },
]);

const overvaluationRiskScore =
  valuationScore === null ? null : 100 - valuationScore;

// ============================================================
// Data Quality
// ============================================================

const required = {
  pe_ratio: pe,
  ev_ebitda: evEbitda,
  fcf_yield: fcfYield,
  ev_sales: evSales,
  revenue_growth: revenueGrowth,
  gross_margin: grossMargin,
  operating_margin: operatingMargin,
  roe: roe,
  enterprise_value: enterpriseValue,
  revenue_per_ev: revenuePerEV,
  ebitda_per_ev: ebitdaPerEV,
  fcf_per_ev: fcfPerEV,
};

const missing = Object.entries(required)
  .filter(([k, v]) => v === null || v === undefined || !Number.isFinite(v))
  .map(([k]) => k);

const dataQualityScore = round2(
  ((Object.keys(required).length - missing.length) /
    Object.keys(required).length) *
    100
);

// ============================================================
// Final Output
// ============================================================

return [
  {
    json: {
      run_date_sgt: runDate,
      ticker,
      company_name: base.company_name || null,
      ai_subsector: base.ai_subsector || null,

      price: round2(price),
      market_cap: marketCap,

      pe_ratio: round2(pe),
      ev_ebitda: round2(evEbitda),
      ev_sales: round2(evSales),
      price_to_sales: round2(ps),
      price_to_book: round2(pb),
      fcf_yield: round4(fcfYield),
      earnings_yield: round4(earningsYield),

      enterprise_value: enterpriseValue,
      revenue: revenue,
      ebitda: ebitda,
      free_cash_flow: freeCashFlow,

      revenue_per_ev: round4(revenuePerEV),
      ebitda_per_ev: round4(ebitdaPerEV),
      fcf_per_ev: round4(fcfPerEV),

      revenue_growth: round4(revenueGrowth),
      net_income_growth: round4(netIncomeGrowth),
      gross_margin: round4(grossMargin),
      operating_margin: round4(operatingMargin),
      net_margin: round4(netMargin),
      roe: round4(roe),
      roic: round4(roic),

      debt_to_equity: round2(debtToEquity),
      net_debt_to_ebitda: round2(netDebtToEbitda),

      pe_score: round2(peScore),
      ev_ebitda_score: round2(evEbitdaScore),
      fcf_yield_score: round2(fcfYieldScore),
      ev_sales_score: round2(evSalesScore),
      growth_score: round2(growthScore),
      quality_score: round2(qualityScore),
      balance_sheet_score: round2(balanceSheetScore),
      valuation_score: round2(valuationScore),
      growth_quality_score: round2(growthQualityScore),
      fundamental_score: round2(fundamentalScore),
      overvaluation_risk_score: round2(overvaluationRiskScore),

      data_quality_score: dataQualityScore,
      missing_fields: missing.join(', '),
      source: 'financial_modeling_prep',
    },
  },
];

return [{
  json: {
    run_date_sgt: $json.run_date_sgt,
    ticker: $json.ticker,
    pe_ratio: $json.pe_ratio,
    ev_ebitda: $json.ev_ebitda,
    fcf_yield: $json.fcf_yield,
    pe_score: $json.pe_score,
    ev_ebitda_score: $json.ev_ebitda_score,
    fcf_yield_score: $json.fcf_yield_score,
    valuation_score: $json.valuation_score,
    source: 'financial_modeling_prep'
  }
}];

const toNum = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const round2 = v => (v === null || v === undefined || !Number.isFinite(v)) ? null : Math.round(v * 100) / 100;

let daily = {};
try {
  const d = $('Fetch Today Stock Daily Metrics').first().json;
  daily = Array.isArray(d) ? (d[0] || {}) : d;
} catch (e) {}

const q = $json || {};
const momentum = toNum(daily.momentum_score);
const valuationProxy = toNum(daily.valuation_proxy);
const overvaluationRisk = toNum(q.overvaluation_risk_score);
const fundamental = toNum(q.fundamental_score);

let signal = 'Neutral';
if (overvaluationRisk !== null && momentum !== null) {
  if (overvaluationRisk >= 70 && momentum >= 65) signal = 'Overheated AI Risk';
  else if (overvaluationRisk >= 70 && momentum < 50) signal = 'Expensive / Losing Momentum';
  else if (overvaluationRisk <= 35 && momentum >= 60) signal = 'Fundamental Momentum Leader';
  else if (overvaluationRisk <= 35 && momentum < 50) signal = 'Potential Value Watch';
}

const explanationParts = [];
if (q.valuation_score !== null && q.valuation_score !== undefined) explanationParts.push(`Valuation score ${q.valuation_score}`);
if (fundamental !== null) explanationParts.push(`fundamental score ${round2(fundamental)}`);
if (momentum !== null) explanationParts.push(`momentum score ${round2(momentum)}`);
if (valuationProxy !== null) explanationParts.push(`price-vs-200DMA proxy ${round2(valuationProxy)}%`);

return [{
  json: {
    run_date_sgt: q.run_date_sgt,
    ticker: q.ticker || daily.ticker,
    company_name: q.company_name || daily.company_name || null,
    ai_subsector: q.ai_subsector || daily.ai_subsector || null,
    latest_price: daily.latest_price ?? q.price ?? null,
    day_change_pct: daily.day_change_pct ?? null,
    momentum_score: daily.momentum_score ?? null,
    valuation_proxy: daily.valuation_proxy ?? null,
    composite_score: daily.composite_score ?? null,
    valuation_score: q.valuation_score ?? null,
    growth_quality_score: q.growth_quality_score ?? null,
    fundamental_score: q.fundamental_score ?? null,
    overvaluation_risk_score: q.overvaluation_risk_score ?? null,
    signal_label: signal,
    explanation: explanationParts.join(' | '),
    source: 'fmp_quant_stack'
  }
}];

const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Singapore',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(new Date());

const run_date_sgt = `${parts.find(p => p.type === 'year').value}-${parts.find(p => p.type === 'month').value}-${parts.find(p => p.type === 'day').value}`;

return [{ json: { run_date_sgt } }];

const toNum = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const round2 = v => (v === null || v === undefined || !Number.isFinite(v)) ? null : Math.round(v * 100) / 100;

const avg = arr => {
  const nums = arr.map(toNum).filter(v => v !== null);
  if (!nums.length) return null;
  return nums.reduce((a,b) => a+b, 0) / nums.length;
};

let rows = [];
for (const item of $input.all()) {
  if (Array.isArray(item.json)) rows.push(...item.json);
  else if (Array.isArray(item.json?.data)) rows.push(...item.json.data);
  else rows.push(item.json);
}

rows = rows.filter(r => r && r.run_date_sgt && r.ai_subsector);

const groups = {};
for (const r of rows) {
  const key = `${r.run_date_sgt}||${r.ai_subsector}`;
  if (!groups[key]) groups[key] = [];
  groups[key].push(r);
}

const out = [];
for (const [key, group] of Object.entries(groups)) {
  const [runDate, subsector] = key.split('||');
  const valid = group.filter(r => toNum(r.fundamental_score) !== null);
  const weak = [...valid].sort((a,b) => toNum(a.fundamental_score) - toNum(b.fundamental_score));
  const strong = [...valid].sort((a,b) => toNum(b.fundamental_score) - toNum(a.fundamental_score));

  out.push({
    json: {
      run_date_sgt: runDate,
      ai_subsector: subsector,
      stock_count: group.length,
      avg_valuation_score: round2(avg(group.map(r => r.valuation_score))),
      avg_growth_quality_score: round2(avg(group.map(r => r.growth_quality_score))),
      avg_fundamental_score: round2(avg(group.map(r => r.fundamental_score))),
      avg_overvaluation_risk_score: round2(avg(group.map(r => r.overvaluation_risk_score))),
      avg_data_quality_score: round2(avg(group.map(r => r.data_quality_score))),
      weakest_ticker: weak.length ? weak[0].ticker : null,
      strongest_ticker: strong.length ? strong[0].ticker : null
    }
  });
}

return out;
